CREATE OR REPLACE FUNCTION public.pm_quote_calendar_stages(_quote uuid,_start date) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE rows jsonb; row jsonb; dep quote_stage_dependencies; pred jsonb; candidate_start date; candidate_end date; best_start date; best_end date; duration integer; delta integer; pass integer; changed boolean; child record; parent record; bounds record; BEGIN SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'parent_stage_id',s.parent_stage_id,'start_date',CASE WHEN s.stage_kind='retainer_monthly' THEN date_trunc('month',pm_calendar_shift(_start,pm_relative_offset(s.start_date)))::date ELSE pm_calendar_shift(_start,pm_relative_offset(s.start_date)) END,'end_date',CASE WHEN s.stage_kind='retainer_monthly' THEN (date_trunc('month',pm_calendar_shift(_start,pm_relative_offset(s.start_date)))+make_interval(months=>greatest(1,coalesce(s.retainer_months,1)))-interval '1 day')::date ELSE pm_calendar_shift(_start,pm_relative_offset(s.end_date)) END,'duration',pm_relative_offset(s.end_date)-pm_relative_offset(s.start_date)+1,'stage_kind',s.stage_kind,'retainer_months',s.retainer_months,'retainer_monthly_amount',s.retainer_monthly_amount) ORDER BY s.sort_order,s.id),'[]'::jsonb) INTO rows FROM quote_stages s WHERE quote_id=_quote; IF EXISTS(WITH RECURSIVE edges(a,b) AS(SELECT predecessor_stage_id,successor_stage_id FROM quote_stage_dependencies WHERE quote_id=_quote UNION ALL SELECT id,parent_stage_id FROM quote_stages WHERE quote_id=_quote AND parent_stage_id IS NOT NULL), paths(a,b,seen,cycle) AS(SELECT a,b,ARRAY[a,b],a=b FROM edges UNION ALL SELECT p.a,e.b,p.seen||e.b,e.b=ANY(p.seen) FROM paths p JOIN edges e ON p.b=e.a WHERE NOT p.cycle) SELECT 1 FROM paths WHERE cycle) THEN RAISE EXCEPTION 'gantt.schedule.cycle'; END IF; FOR pass IN 0..greatest(1,jsonb_array_length(rows)*3) LOOP changed:=false; FOR parent IN SELECT id FROM quote_stages WHERE quote_id=_quote AND EXISTS(SELECT 1 FROM quote_stages c WHERE c.parent_stage_id=quote_stages.id) LOOP SELECT min(value->>'start_date')::date start_date,max(value->>'end_date')::date end_date INTO bounds FROM jsonb_array_elements(rows) WHERE value->>'parent_stage_id'=parent.id::text; SELECT value INTO row FROM jsonb_array_elements(rows) WHERE value->>'id'=parent.id::text; IF row->>'start_date'<>bounds.start_date::text OR row->>'end_date'<>bounds.end_date::text THEN SELECT jsonb_agg(CASE WHEN value->>'id'=parent.id::text THEN value||jsonb_build_object('start_date',bounds.start_date,'end_date',bounds.end_date) ELSE value END) INTO rows FROM jsonb_array_elements(rows); changed:=true; END IF; END LOOP; FOR row IN SELECT value FROM jsonb_array_elements(rows) LOOP best_start:=NULL; best_end:=NULL; duration:=(row->>'duration')::integer; IF EXISTS(SELECT 1 FROM quote_stages c WHERE c.parent_stage_id=(row->>'id')::uuid) THEN WITH RECURSIVE descendants AS(SELECT id,parent_stage_id,start_date,end_date FROM quote_stages WHERE id=(row->>'id')::uuid UNION ALL SELECT c.id,c.parent_stage_id,c.start_date,c.end_date FROM quote_stages c JOIN descendants d ON c.parent_stage_id=d.id) SELECT pm_relative_offset(max(end_date))-pm_relative_offset(min(start_date))+1 INTO duration FROM descendants d WHERE NOT EXISTS(SELECT 1 FROM quote_stages c WHERE c.parent_stage_id=d.id); END IF; FOR dep IN SELECT * FROM quote_stage_dependencies WHERE quote_id=_quote AND successor_stage_id=(row->>'id')::uuid LOOP SELECT value INTO pred FROM jsonb_array_elements(rows) WHERE value->>'id'=dep.predecessor_stage_id::text; IF dep.type::text IN('FS','SS') THEN candidate_start:=pm_calendar_shift(CASE WHEN dep.type::text='FS' THEN (pred->>'end_date')::date ELSE (pred->>'start_date')::date END,dep.lag_days+CASE WHEN dep.type::text='FS' THEN 1 ELSE 0 END); candidate_end:=pm_calendar_shift(candidate_start,duration-1); ELSE candidate_end:=pm_calendar_shift(CASE WHEN dep.type::text='FF' THEN (pred->>'end_date')::date ELSE (pred->>'start_date')::date END,dep.lag_days); candidate_start:=pm_calendar_shift(candidate_end,1-duration); END IF; IF best_start IS NULL OR candidate_start>best_start THEN best_start:=candidate_start; best_end:=candidate_end; END IF; END LOOP; IF best_start IS NULL THEN CONTINUE; END IF; IF row->>'stage_kind'='retainer_monthly' THEN best_start:=date_trunc('month',best_start)::date; best_end:=(best_start+make_interval(months=>(row->>'retainer_months')::integer)-interval '1 day')::date; END IF; IF row->>'start_date'=best_start::text AND row->>'end_date'=best_end::text THEN CONTINUE; END IF; IF EXISTS(SELECT 1 FROM quote_stages WHERE parent_stage_id=(row->>'id')::uuid) THEN SELECT count(*)::integer INTO delta FROM generate_series(least((row->>'start_date')::date,best_start)::timestamp,greatest((row->>'start_date')::date,best_start)::timestamp-interval '1 day',interval '1 day') d WHERE extract(isodow FROM d)<6 AND NOT EXISTS(SELECT 1 FROM holidays h WHERE h.data=d::date); IF best_start<(row->>'start_date')::date THEN delta:=-delta; END IF; FOR child IN WITH RECURSIVE descendants AS(SELECT id FROM quote_stages WHERE parent_stage_id=(row->>'id')::uuid UNION ALL SELECT c.id FROM quote_stages c JOIN descendants d ON c.parent_stage_id=d.id) SELECT id FROM descendants WHERE NOT EXISTS(SELECT 1 FROM quote_stages c WHERE c.parent_stage_id=descendants.id) LOOP SELECT jsonb_agg(CASE WHEN value->>'id'=child.id::text THEN value||jsonb_build_object('start_date',pm_calendar_shift((value->>'start_date')::date,delta),'end_date',pm_calendar_shift(pm_calendar_shift((value->>'start_date')::date,delta),(value->>'duration')::integer-1)) ELSE value END) INTO rows FROM jsonb_array_elements(rows); END LOOP; END IF; SELECT jsonb_agg(CASE WHEN value->>'id'=row->>'id' THEN value||jsonb_build_object('start_date',best_start,'end_date',best_end) ELSE value END) INTO rows FROM jsonb_array_elements(rows); changed:=true; END LOOP; IF NOT changed THEN RETURN rows; END IF; END LOOP; RAISE EXCEPTION 'gantt.schedule.invalidLink'; END $$;
CREATE OR REPLACE FUNCTION public.pm_quote_calendar_allocations(_quote uuid,_start date) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE stages jsonb; rows jsonb:='[]'; a record; bounds jsonb; first_day date; last_day date; duration integer; workdays integer; m integer; BEGIN stages:=pm_quote_calendar_stages(_quote,_start); FOR a IN SELECT a.*,s.stage_kind,s.retainer_months,s.start_date stage_start FROM quote_allocations a JOIN quote_stages s ON s.id=a.stage_id WHERE a.quote_id=_quote LOOP SELECT value INTO bounds FROM jsonb_array_elements(stages) WHERE value->>'id'=a.stage_id::text; duration:=pm_relative_offset(a.end_date)-pm_relative_offset(a.start_date)+1; IF a.stage_kind='retainer_monthly' THEN FOR m IN 0..greatest(0,coalesce(a.retainer_months,1)-1) LOOP first_day:=((bounds->>'start_date')::date+make_interval(months=>m))::date; last_day:=(first_day+interval '1 month'-interval '1 day')::date; SELECT count(*) INTO workdays FROM generate_series(first_day::timestamp,last_day::timestamp,interval '1 day') d WHERE extract(isodow FROM d)<6 AND NOT EXISTS(SELECT 1 FROM holidays h WHERE h.data=d::date); IF workdays=0 THEN RAISE EXCEPTION 'gantt.schedule.invalidRange'; END IF; rows:=rows||jsonb_build_array(jsonb_build_object('id',a.id,'stage_id',a.stage_id,'resource_id',a.resource_id,'resource_name',(SELECT name FROM pm_resources WHERE id=a.resource_id),'month_index',m,'hours_per_day',duration*a.hours_per_day/workdays,'start_date',first_day,'end_date',last_day)); END LOOP; ELSE first_day:=pm_calendar_shift((bounds->>'start_date')::date,pm_relative_offset(a.start_date)-pm_relative_offset(a.stage_start)); last_day:=pm_calendar_shift(first_day,duration-1); rows:=rows||jsonb_build_array(jsonb_build_object('id',a.id,'stage_id',a.stage_id,'resource_id',a.resource_id,'resource_name',(SELECT name FROM pm_resources WHERE id=a.resource_id),'hours_per_day',a.hours_per_day,'start_date',first_day,'end_date',last_day)); END IF; END LOOP; RETURN rows; END $$;
REVOKE ALL ON FUNCTION public.pm_quote_calendar_stages(uuid,date),public.pm_quote_calendar_allocations(uuid,date) FROM PUBLIC,anon,authenticated;
DO $migration$ DECLARE definition text; start_at integer; end_at integer; BEGIN SELECT pg_get_functiondef('public.pm_quote_conversion_preview(uuid,date)'::regprocedure) INTO definition; start_at:=strpos(definition,'SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',s.id'); end_at:=strpos(definition,'allocations:='); IF start_at=0 OR end_at<=start_at THEN RAISE EXCEPTION 'Unexpected preview definition'; END IF; definition:=left(definition,start_at-1)||'dates:=pm_quote_calendar_stages(_quote,start_day);'||chr(10)||substr(definition,end_at); EXECUTE definition; END $migration$;